.libPaths(c(normalizePath('work/gdf15/R-library'),.libPaths()))
meta<-read.delim('work/gdf15/data/ena_runs.tsv')
stopifnot(all(file.exists(paste0('work/gdf15/data/clean/',meta$run_accession,'.qc_passed'))))
q<-do.call(rbind,lapply(1:4,function(w)read.csv(paste0('outputs/qc/clean_qc_summary_worker',w,'.csv'))))
cy<-do.call(rbind,lapply(1:4,function(w)read.csv(paste0('outputs/qc/clean_quality_by_cycle_worker',w,'.csv'))))
len<-do.call(rbind,lapply(1:4,function(w)read.csv(paste0('outputs/qc/clean_length_distribution_worker',w,'.csv'))))
stopifnot(nrow(q)==32,length(unique(q$run))==16,!anyDuplicated(paste(q$run,q$end)))
q<-q[order(q$sample,q$end),];q$raw_pairs<-meta$read_count[match(q$run,meta$run_accession)];q$retained_pct<-100*q$clean_pairs/q$raw_pairs
write.csv(q,'outputs/qc/clean_qc_summary.csv',row.names=FALSE);write.csv(cy,'outputs/qc/clean_quality_by_cycle.csv',row.names=FALSE);write.csv(len,'outputs/qc/clean_length_distribution.csv',row.names=FALSE)
trims<-lapply(meta$run_accession,function(run){j<-jsonlite::fromJSON(paste0('outputs/qc/trimming/',run,'.json'));data.frame(run=run,input_pairs=j$read_counts$input,output_pairs=j$read_counts$output,removed_short_pairs=j$read_counts$filtered$too_short,R1_adapter_reads=j$read_counts$read1_with_adapter,R2_adapter_reads=j$read_counts$read2_with_adapter,quality_trimmed_bases=j$basepair_counts$quality_trimmed,raw_bytes=sum(file.info(paste0('work/gdf15/data/raw/',run,'_',1:2,'.fastq.gz'))$size),clean_bytes=sum(file.info(paste0('work/gdf15/data/clean/',run,'_',1:2,'.fastq.gz'))$size))})
write.csv(do.call(rbind,trims),'outputs/qc/trimming_summary.csv',row.names=FALSE)
raw<-read.csv('outputs/qc/raw_qc_summary.csv');raw<-raw[match(paste(q$run,q$end),paste(raw$run,raw$end)),]
png('outputs/qc/raw_vs_clean_Q30.png',width=1800,height=1000,res=160)
par(mar=c(9,5,3,1));barplot(rbind(raw$Q30_pct,q$Q30_pct),beside=TRUE,names.arg=paste(q$sample,paste0('R',q$end)),las=2,cex.names=.65,col=c('#8DA0CB','#66C2A5'),ylim=c(0,100),ylab='Q30 bases (%)',main='RNA-seq quality before and after trimming');legend('bottomleft',legend=c('Raw: 0.5% sample','Clean: 100,000 sampled reads/end'),fill=c('#8DA0CB','#66C2A5'),bty='n');dev.off()
png('outputs/qc/clean_quality_by_cycle.png',width=1600,height=1000,res=150);par(mfrow=c(1,2),mar=c(4,4,3,1))
for(e in 1:2){plot(NA,xlim=c(1,51),ylim=c(20,36),xlab='Read position (bp)',ylab='Mean Phred score',main=paste('Clean reads: end',e));for(i in seq_len(nrow(meta))){z<-cy[cy$run==meta$run_accession[i]&cy$end==e,];lines(z$cycle,z$mean_phred,col=i)}};dev.off()
writeLines(c('Clean files fully parsed with FastqSampler; per-end total read counts match Cutadapt output exactly.','Quality/adapter/length metrics use independent uniform reservoir samples of 100,000 reads/end. Independent samples are not used for pair ID matching.','Raw files had full paired-ID validation; Cutadapt processes and retains/discards matched pairs jointly.','Phred Q20 trimming; Illumina 3-prime adapters; error rate 0.1; overlap >=3; minimum length20; pair-filter any.',capture.output(sessionInfo())),'outputs/qc/clean_qc_methods.txt')
writeLines('passed','outputs/qc/clean_qc_passed.txt')
cat('ALL CLEAN QC COMPLETE\n');print(summary(q[,c('retained_pct','Q30_pct','adapter_13mer_pct')]));cat('Clean pairs:',sum(q$clean_pairs)/2,'\n')
